import { notifyUpdateReady } from './update'

/** Keep an already-open tab or installed PWA from sitting on an old release. */
const UPDATE_CHECK_INTERVAL_MS = 5 * 60 * 1000

/**
 * Registers the Workbox service worker generated by vite-plugin-pwa.
 *
 * `vite.config.ts` sets `injectRegister: false` on purpose: registration happens
 * here so the app decides when the worker boots and can tell the reader that a
 * new version has taken over. Production only — there is no `/sw.js` in dev.
 */
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD) {
    return
  }

  if (!('serviceWorker' in navigator)) {
    console.warn('[pwa] service workers are not supported in this browser')
    return
  }

  // Registering after `load` keeps the first paint off the critical path.
  window.addEventListener('load', () => {
    // On first install there is no controller yet. The first controllerchange
    // is the initial worker taking control; only later changes mean a new
    // release has taken over and the already-loaded page needs a reload.
    let hasController = navigator.serviceWorker.controller !== null

    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!hasController) {
        hasController = true
        return
      }

      notifyUpdateReady()
    })

    navigator.serviceWorker
      .register('/sw.js', { scope: '/', updateViaCache: 'none' })
      .then((registration) => {
        let updateCheckInFlight = false

        // Browsers check for worker updates on their own schedule, which can
        // leave an installed PWA on an old release for a long time. Check once
        // now, when the app returns to the foreground, and while it stays open.
        const checkForUpdate = (): void => {
          if (
            updateCheckInFlight ||
            document.visibilityState !== 'visible' ||
            navigator.onLine === false
          ) {
            return
          }

          updateCheckInFlight = true
          void registration.update().catch((error: unknown) => {
            if (navigator.onLine !== false) {
              console.warn('[pwa] service worker update check failed', error)
            }
          }).finally(() => {
            updateCheckInFlight = false
          })
        }

        checkForUpdate()
        window.setInterval(checkForUpdate, UPDATE_CHECK_INTERVAL_MS)
        window.addEventListener('focus', checkForUpdate)
        window.addEventListener('online', checkForUpdate)
        document.addEventListener('visibilitychange', checkForUpdate)
      })
      .catch((error: unknown) => {
        console.error('[pwa] service worker registration failed', error)
      })
  })
}
